 Fixture f;auto before=f.frame;before.units[0].member_ids.push_back("witness");before.units[0].fit.push_back("witness");auto after=before;mark_naval_commander_loss(after.units[0],2);
 auto catalog=std::make_shared<CommonCatalog>();CommonState state;state.identity.tick=3;for(const auto* id:{"captain0","captain1","captain2","witness"}){ActorRecord a;a.id=id;a.alive=a.available=true;a.hp=100;state.actors.insert(id,a);}CommonStore common(state,catalog);auto changes=take(naval_round_actor_changes(common,before,after));MilitaryState military;for(const auto& u:after.units){MilitaryUnitRecord r;r.id=u.unit_id;r.army_id=u.army_id;r.commander_actor_id=u.commander_actor_id;r.member_ids=u.member_ids;r.fit=u.fit;r.wounded=u.wounded;r.dead=u.dead;r.morale=u.morale;military.military_units.push_back(r);}
