 auto wrong=naval;wrong.battle.rounds[0].after.bindings[0].vessel_id="switched";check(!query_military_actor_death_witness(common,military,&wrong,"witness","captain0","military:3").ok,"same unit cannot borrow a different physical vessel");
 MilitaryCasualtyFact later;later.id="military:9";later.battle_id="later-round";later.tick=3;MilitaryActorChange future;future.actor_id="witness";future.status="dead";later.actor_changes={future};military.casualty_facts.push_back(later);common.state().facts.insert(later.id,{later.id,"military_casualties","military"});auto* observer=common.state().actors.find("witness");observer->alive=observer->available=false;observer->hp=0;check(bool(take(query_military_actor_death_witness(common,military,&naval,"witness","captain0","military:3"))),"later observer death does not erase earlier living witness");military.casualty_facts.pop_back();common.state().facts.erase(later.id);observer->alive=observer->available=true;observer->hp=100;
 const auto bytes=take(render_boundary_json(encode_common_state(common.state())));take(query_military_actor_death_witness(common,military,&naval,"witness","captain0","military:3"));check(bytes==take(render_boundary_json(encode_common_state(common.state()))),"knowledge query leaves Common assets and identities byte exact");
