 proof=take(query_military_actor_death_witness(common,land,nullptr,"captain1","captain0",loss.id));check(proof&&proof->unit_id==u.unit_id,"real participating land unit commander witnesses own named casualty");check(bool(take(query_military_actor_death_witness(common,land,nullptr,"witness","captain0",loss.id))),"same unit surviving named member witnesses land death");check(!take(query_military_actor_death_witness(common,land,nullptr,"captain2","captain0",loss.id)),"nonparticipant has no land knowledge source");MilitaryActorChange captive;captive.actor_id="witness";captive.status="captured";land.casualty_facts[0].actor_changes.push_back(captive);check(!take(query_military_actor_death_witness(common,land,nullptr,"witness","captain0",loss.id)),"same-round unavailable observer is not presumed a live witness");
